import React,{useEffect,useMemo,useState}from'react';import{createRoot}from'react-dom/client';import{BrowserRouter,NavLink,useNavigate}from'react-router-dom';import{LayoutDashboard,CheckSquare,Sparkles,CalendarDays,Columns3,Timer,BarChart3,Settings,LogOut,Plus,Mic,Send,Play,Pause,RotateCcw,CircleHelp,Trash2,Bell,Search,Download,FolderKanban,Paperclip,Users}from'lucide-react';import{BarChart,Bar,XAxis,YAxis,Tooltip,ResponsiveContainer}from'recharts';import'./style.css';
const API=import.meta.env.VITE_API_URL||'http://localhost:5000/api';
async function call(path,method='GET',body){const token=localStorage.getItem('tm_token');const r=await fetch(API+path,{method,headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:body?JSON.stringify(body):undefined});const data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.error?.message||'Request failed');return data}
function offlineOperations(){try{const value=JSON.parse(localStorage.getItem('tm_offline_queue')||'[]');if(!Array.isArray(value))throw Error();return value}catch{throw Error('Offline changes could not be read from local storage.')}}
function enqueueOffline(operation){const queue=offlineOperations();queue.push(operation);localStorage.setItem('tm_offline_queue',JSON.stringify(queue))}
function enqueueDeletion(taskId,userId){let queue=offlineOperations();if(taskId<0){const create=queue.find(operation=>operation.type==='create'&&operation.local_id===taskId);queue=queue.filter(operation=>operation.local_id!==taskId&&operation.task_id!==taskId);if(create?.synced_task_id)queue.push({type:'delete',user_id:userId,task_id:create.synced_task_id})}else queue.push({type:'delete',user_id:userId,task_id:taskId});localStorage.setItem('tm_offline_queue',JSON.stringify(queue))}
function resetTokenFromLocation(){return new URLSearchParams(window.location.hash.slice(1)).get('reset_token')||new URLSearchParams(window.location.search).get('reset_token')||''}
function mergeOfflineTasks(tasks,userId){const queue=offlineOperations().filter(operation=>operation.user_id===userId),result=[...tasks],localIds=new Map(),deleted=new Set();for(const operation of queue)if(operation.type==='create'){const serverId=operation.synced_task_id||null;if(serverId){localIds.set(operation.local_id,serverId);if(!result.some(task=>task.id===serverId))result.unshift({...operation.task,id:serverId,status:'todo',tags:operation.task.tags||[],subtasks:[],dependencies:[],projects:[],offline_pending:true})}else if(!result.some(task=>task.id===operation.local_id))result.unshift({...operation.task,id:operation.local_id,status:'todo',tags:operation.task.tags||[],subtasks:[],dependencies:[],projects:[],offline_pending:true})}for(const operation of queue)if(operation.type==='status'){const id=localIds.get(operation.task_id)||operation.task_id;for(const task of result)if(task.id===id)Object.assign(task,{status:operation.status,offline_pending:true})}for(const operation of queue)if(operation.type==='delete')deleted.add(localIds.get(operation.task_id)||operation.task_id);return result.filter(task=>!deleted.has(task.id))}
const nav=[['Dashboard',LayoutDashboard],['My Tasks',CheckSquare],['Projects',FolderKanban],['Collaboration',Users],['AI Assistant',Sparkles],['Smart Scheduler',CalendarDays],['Calendar',CalendarDays],['Task Progress Board',Columns3],['Analytics',BarChart3],['Focus Mode',Timer],['Notifications',Bell],['Settings',Settings]];
function Hint({children}){const[open,setOpen]=useState(false);return <span className="hint"><button type="button" onClick={()=>setOpen(!open)} aria-label="Show help"><CircleHelp size={15}/></button>{open&&<span className="hintText">{children}</span>}</span>}
function Toast({notice,onClose}){useEffect(()=>{const timer=setTimeout(onClose,5000);return()=>clearTimeout(timer)},[notice.id]);return <div className={'toast '+notice.type} role="status" aria-live={notice.type==='error'?'assertive':'polite'}><span className="toastIcon">{notice.type==='error'?'!':'✓'}</span><div><b>{notice.title}</b><p>{notice.message}</p></div><button onClick={onClose} aria-label="Dismiss notification">×</button></div>}
function Auth({onDone}){const[register,setRegister]=useState(false),[forgot,setForgot]=useState(false),[resetToken,setResetToken]=useState(resetTokenFromLocation),[error,setError]=useState(''),[message,setMessage]=useState('');async function submit(e){e.preventDefault();setError('');setMessage('');const values=Object.fromEntries(new FormData(e.target));try{if(resetToken){if(values.password!==values.confirm_password){setError('Passwords do not match.');return}const result=await call('/auth/password-reset/confirm','POST',{token:resetToken,password:values.password});localStorage.removeItem('tm_token');localStorage.removeItem('tm_user_cache');setMessage(result.message);setResetToken('');window.history.replaceState({},document.title,window.location.pathname);return}if(forgot){const result=await call('/auth/password-reset/request','POST',{email:values.email});setMessage(result.message);return}const d=await call('/auth/'+(register?'register':'login'),'POST',values);localStorage.setItem('tm_token',d.access_token);localStorage.setItem('tm_user_cache',JSON.stringify(d.user));onDone(d.user)}catch(e){setError(e.message)}}const title=resetToken?'Set a new password':forgot?'Reset your password':register?'Create your workspace':'Welcome back';return <main className="auth"><div className="brand">✓ <span>TaskMaster</span> Pro</div><h1>{title}</h1><p>Plan with clarity. Finish with momentum.</p><form onSubmit={submit}>{register&&!resetToken&&<input name="name" placeholder="Your name" required/>}{!resetToken&&<input name="email" type="email" placeholder="Email address" required/>}{!forgot&&<><input name="password" type="password" placeholder={resetToken?'New password (8+ characters)':'Password (8+ characters)'} minLength="8" required/>{resetToken&&<input name="confirm_password" type="password" placeholder="Confirm new password" minLength="8" required/>}</>}{error&&<small className="error">{error}</small>}{message&&<small className="successMessage">{message}</small>}<button>{resetToken?'Update password':forgot?'Send reset link':register?'Create account':'Sign in'}</button></form>{!resetToken&&<><button className="text" onClick={()=>{setForgot(!forgot);setError('');setMessage('')}}>{forgot?'Back to sign in':"Forgot password?"}</button>{!forgot&&<button className="text" onClick={()=>{setRegister(!register);setError('');setMessage('')}}>{register?'Already have an account? Sign in':'New here? Create an account'}</button>}</>}</main>}
function TaskCard({task,onStatus,onDelete,allTasks,onDependencies,onUploadAttachment,onDeleteAttachment,onDownloadAttachment}){const[dependencyIds,setDependencyIds]=useState(task.dependencies||[]);useEffect(()=>setDependencyIds(task.dependencies||[]),[task.dependencies]);async function changeDependencies(e){const ids=Array.from(e.target.selectedOptions,option=>Number(option.value));setDependencyIds(ids);if(!await onDependencies(task.id,ids))setDependencyIds(task.dependencies||[])}return <article className={'task '+task.priority}><div><span className="pill">{task.priority}</span>{task.offline_pending&&<span className="pill offlinePill">Pending sync</span>}{task.recurrence&&<span className="pill recurringPill">Repeats {task.recurrence.frequency}</span>}<h3>{task.title}</h3><p>{task.description||'No description'}</p>{task.projects?.length>0&&<small className="taskProjects">{task.projects.map(project=>project.name).join(' · ')}</small>}{onDependencies&&task.id>0&&<details className="dependencyEditor"><summary>Dependencies ({dependencyIds.length})</summary><p>Hold Ctrl while selecting to choose multiple prerequisites.</p><select multiple size={Math.min(Math.max(allTasks.length,2),5)} aria-label={`Tasks that must be completed before ${task.title}`} value={dependencyIds.map(String)} onChange={changeDependencies}>{allTasks.filter(t=>t.id!==task.id).map(t=><option key={t.id} value={t.id}>{t.title} · {t.status.replace('_',' ')}</option>)}</select></details>}{onUploadAttachment&&task.id>0&&<details className="attachmentEditor"><summary><Paperclip size={14}/> Attachments</summary><TaskAttachments taskId={task.id} onUpload={onUploadAttachment} onDelete={onDeleteAttachment} onDownload={onDownloadAttachment}/></details>}</div><footer><span>{task.due_date?'Due '+new Date(task.due_date).toLocaleDateString():'No deadline'}</span><div><select aria-label="Task status" value={task.status} onChange={e=>onStatus(task.id,e.target.value)}><option value="todo">To do</option><option value="in_progress">In progress</option><option value="completed">Completed</option></select>{onDelete&&task.id>0&&<button className="iconButton" title="Delete task" onClick={()=>{if(confirm('Delete this task?'))onDelete(task.id)}}><Trash2 size={15}/></button>}</div></footer></article>}
function TaskAttachments({taskId,onUpload,onDelete,onDownload}){const[attachments,setAttachments]=useState([]),[error,setError]=useState('');async function load(){try{setAttachments((await call(`/tasks/${taskId}/attachments`)).attachments);setError('')}catch(e){setError(e.message)}}useEffect(()=>{load()},[taskId]);async function upload(e){const file=e.target.files?.[0];e.target.value='';if(!file)return;if(await onUpload(taskId,file))load()}return <div className="attachmentList"><label className="secondary attachmentUpload"><Plus size={14}/>Add file<input type="file" accept=".pdf,.txt,.md,.csv,.docx,.xlsx,.png,.jpg,.jpeg,.gif,.webp" onChange={upload}/></label>{error&&<small className="error">{error}</small>}{attachments.map(item=><div className="attachmentItem" key={item.id}><button className="text" onClick={()=>onDownload(item.id,item.filename)}>{item.filename}</button><small>{Math.max(1,Math.round(item.size_bytes/1024))} KB</small><button className="text" aria-label={`Delete ${item.filename}`} onClick={async()=>{if(await onDelete(item.id))load()}}>Remove</button></div>)}</div>}
function NewTask({onAdd}){const[open,setOpen]=useState(false),[title,setTitle]=useState(''),[voice,setVoice]=useState('');function speak(){const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){setVoice('Voice input is not supported in this browser. Try Chrome or Edge.');return}const r=new Recognition();r.lang='en-US';r.interimResults=false;setVoice('Listening… speak your task title.');r.onresult=e=>{setTitle(e.results[0][0].transcript);setVoice('Voice captured — you can edit it before saving.')};r.onerror=()=>setVoice('Could not access the microphone. Check browser permission.');r.start()}async function submit(e){e.preventDefault();const f=new FormData(e.target),frequency=f.get('recurrence'),recurrence=frequency==='none'?null:{frequency,interval:+f.get('recurrence_interval')};const saved=await onAdd({title,description:f.get('description'),priority:f.get('priority'),category:f.get('category'),due_date:f.get('due_date')||null,estimated_minutes:+f.get('estimated_minutes'),recurrence});if(saved===false)return;e.target.reset();setTitle('');setOpen(false)}return <><button className="primary" onClick={()=>setOpen(true)}><Plus/> Add task</button>{open&&<div className="modal"><form onSubmit={submit}><h2>Create task</h2><label>Task title <Hint>Name the work you want to complete.</Hint><div className="voiceInput"><input name="title" value={title} onChange={e=>setTitle(e.target.value)} placeholder="What needs doing?" required/><button type="button" title="Speak task title" onClick={speak}><Mic size={17}/></button></div>{voice&&<small>{voice}</small>}</label><label>Description <span className="optional">optional</span><Hint>Add useful context, steps, or acceptance criteria.</Hint><textarea name="description" placeholder="Add useful context or acceptance criteria"/></label><div className="row"><label>Priority <Hint>Urgent needs immediate attention; High is important soon; Medium is normal; Low can wait.</Hint><select name="priority"><option value="medium">Medium — normal importance</option><option value="high">High — important soon</option><option value="urgent">Urgent — needs immediate attention</option><option value="low">Low — do when time allows</option></select></label><label>Category <Hint>Groups related tasks and improves analytics filtering.</Hint><input name="category" placeholder="e.g. Work, Study" defaultValue="General"/></label></div><label>Due date <span className="optional">optional</span><Hint>When the task must be finished. It helps identify overdue work and plan the schedule.</Hint><input name="due_date" type="datetime-local"/></label><label>Estimated duration (minutes) <Hint>How long you expect this task to take.</Hint><input name="estimated_minutes" type="number" min="0" defaultValue="30"/></label><div className="row"><label>Repeat <select name="recurrence"><option value="none">Does not repeat</option><option value="daily">Daily</option><option value="weekly">Weekly</option><option value="monthly">Monthly</option></select></label><label>Every <select name="recurrence_interval"><option value="1">1 interval</option><option value="2">2 intervals</option><option value="3">3 intervals</option><option value="4">4 intervals</option></select></label></div><small className="recurrenceHelp">Completing a repeating task automatically creates its next occurrence.</small><div className="row"><button className="text" type="button" onClick={()=>setOpen(false)}>Cancel</button><button>Create task</button></div></form></div>}</>}
function App(){
  const[user,setUser]=useState(null),[page,setPage]=useState('Dashboard'),[tasks,setTasks]=useState([]),[overview,setOverview]=useState(null),[error,setError]=useState(''),[notice,setNotice]=useState(null),[desktopEnabled,setDesktopEnabled]=useState(()=>Boolean(window.Notification&&Notification.permission==='granted')),[focusMode,setFocusMode]=useState(false);
  useEffect(()=>{if(import.meta.env.PROD&&'serviceWorker'in navigator)navigator.serviceWorker.register('/service-worker.js').catch(e=>setError(`Offline app shell could not be cached: ${e.message}`))},[]);
  const announce=(title,message,type='success')=>{const next={id:Date.now(),title,message,type};setNotice(next);if(desktopEnabled&&window.Notification&&Notification.permission==='granted')new Notification(title,{body:message,tag:`taskmaster-${title}-${Date.now()}`})};
  const enableDesktopNotifications=async()=>{if(!window.Notification){announce('Desktop notifications unavailable','Your browser does not support desktop notifications.');return}try{const permission=await Notification.requestPermission();if(permission==='granted'){setDesktopEnabled(true);announce('Desktop notifications enabled','You will receive alerts for important task updates.')}else{setDesktopEnabled(false);announce('Desktop notifications not enabled','Allow notifications in your browser settings to receive desktop alerts.','error')}}catch(e){announce('Could not enable notifications',e.message||'Check your browser notification settings.','error')}};
  const load=async()=>{try{const[t,o]=await Promise.all([call('/tasks'),call('/analytics/overview')]);setTasks(mergeOfflineTasks(t.tasks,user.id));setOverview(o);setError('');try{localStorage.setItem(`tm_cache_${user.id}`,JSON.stringify({tasks:t.tasks,overview:o}))}catch(e){setError(`Task cache could not be saved: ${e.message}`)}}catch(e){if(!navigator.onLine&&user){try{const cached=JSON.parse(localStorage.getItem(`tm_cache_${user.id}`)||'{}');setTasks(mergeOfflineTasks(Array.isArray(cached.tasks)?cached.tasks:[],user.id));setOverview(cached.overview||null);setError('Offline mode: showing saved tasks; pending changes will sync when connected.')}catch(cacheError){setError(cacheError.message)}}else setError(e.message)}};
  useEffect(()=>{if(resetTokenFromLocation())return;if(localStorage.getItem('tm_token'))call('/auth/me').then(data=>{setUser(data);localStorage.setItem('tm_user_cache',JSON.stringify(data))}).catch(e=>{if(!navigator.onLine||e instanceof TypeError){try{const cached=JSON.parse(localStorage.getItem('tm_user_cache')||'null');if(cached?.id){setUser(cached);setError('Offline mode: signed in with this device’s cached account.')}else setError('Cannot open offline mode because this device has no cached account.')}catch{setError('Cached account data is invalid; connect to the internet and sign in again.')}return}localStorage.removeItem('tm_token');localStorage.removeItem('tm_user_cache')})},[]);
  useEffect(()=>{if(user)document.documentElement.dataset.theme=user.preferences?.theme||'light'},[user]);
  useEffect(()=>{if(user)load()},[user]);
  useEffect(()=>{if(!user)return;const sync=()=>call('/notifications').catch(e=>setError(e.message));sync();const timer=setInterval(sync,300000);return()=>clearInterval(timer)},[user]);
  useEffect(()=>{if(!user)return;async function syncOffline(){let queue;try{queue=offlineOperations()}catch(e){setError(e.message);return}if(!queue.length)return;if(queue.some(operation=>operation.user_id!==user.id)){setError('Offline changes belong to a different account. Sign in to that account before syncing.');return}const localIds=new Map();let completed=0;try{for(const operation of queue){if(operation.type==='create'){if(!operation.synced_task_id){const result=await call('/tasks','POST',{...operation.task,client_request_id:operation.client_request_id});operation.synced_task_id=result.task.id;localStorage.setItem('tm_offline_queue',JSON.stringify(queue))}localIds.set(operation.local_id,operation.synced_task_id)}else if(operation.type==='status'){const taskId=localIds.get(operation.task_id)||operation.task_id;await call(`/tasks/${taskId}/status`,'PATCH',{status:operation.status})}else if(operation.type==='delete'){const taskId=localIds.get(operation.task_id)||operation.task_id;try{await call(`/tasks/${taskId}`,'DELETE')}catch(e){if(e.message!=='Resource not found.')throw e}}else throw Error('Offline queue contains an unsupported operation.');completed++}}catch(e){setError(`Offline sync paused after ${completed} change${completed===1?'':'s'}: ${e.message}`);return}localStorage.removeItem('tm_offline_queue');await load();announce('Offline changes synced',`${completed} saved change${completed===1?'':'s'} were uploaded.`)}const handleOnline=()=>syncOffline();window.addEventListener('online',handleOnline);if(navigator.onLine)syncOffline();return()=>window.removeEventListener('online',handleOnline)},[user]);
  useEffect(()=>{if(!user)return;const checkDueTasks=()=>{const current=Date.now();tasks.filter(t=>t.status!=='completed'&&t.due_date).forEach(t=>{const due=new Date(t.due_date).getTime();if(!Number.isFinite(due))return;const overdue=due<=current;if(overdue||due-current<86400000){const key=`tm_due_notice_${t.id}_${due}_${overdue?'overdue':'soon'}`;if(!sessionStorage.getItem(key)){sessionStorage.setItem(key,'1');announce(overdue?'Task overdue':'Task due soon',`“${t.title}” is ${overdue?'past its deadline':'due within 24 hours'}.`,'error')}}})};checkDueTasks();const timer=setInterval(checkDueTasks,60000);return()=>clearInterval(timer)},[user,tasks,desktopEnabled]);
  const saveTask=async task=>{if(!navigator.onLine){try{const localId=-Date.now(),client_request_id=crypto.randomUUID();enqueueOffline({type:'create',user_id:user.id,local_id:localId,client_request_id,task});setTasks(current=>[{...task,id:localId,status:'todo',tags:task.tags||[],subtasks:[],dependencies:[],projects:[],offline_pending:true},...current]);announce('Task saved offline',`“${task.title}” will sync when your connection returns.`);return true}catch(e){setError(e.message);announce('Offline task not saved',e.message,'error');return false}}try{await call('/tasks','POST',task);announce('Task created',`“${task.title}” was added to your task list.`);await load();return true}catch(e){if(e instanceof TypeError){try{const localId=-Date.now(),client_request_id=crypto.randomUUID();enqueueOffline({type:'create',user_id:user.id,local_id:localId,client_request_id,task});setTasks(current=>[{...task,id:localId,status:'todo',tags:task.tags||[],subtasks:[],dependencies:[],projects:[],offline_pending:true},...current]);announce('Task saved offline',`“${task.title}” will sync when your connection returns.`);return true}catch(queueError){e=queueError}}setError(e.message);announce('Task not created',e.message,'error');return false}};
  const status=async(id,value)=>{const task=tasks.find(item=>item.id===id);if(!navigator.onLine){try{enqueueOffline({type:'status',user_id:user.id,task_id:id,status:value});setTasks(current=>current.map(item=>item.id===id?{...item,status:value,offline_pending:true}:item));announce('Status saved offline',`“${task?.title||'Task'}” will sync when your connection returns.`);return}catch(e){setError(e.message);announce('Status not saved',e.message,'error');return}}try{const r=await call('/tasks/'+id+'/status','PATCH',{status:value});announce('Task updated',`“${r.task.title}” is now ${value.replace('_',' ')}.`);if(r.next_occurrence)announce('Next recurring task created',`“${r.next_occurrence.title}” is due ${new Date(r.next_occurrence.due_date).toLocaleString()}.`);await load()}catch(e){if(e instanceof TypeError){try{enqueueOffline({type:'status',user_id:user.id,task_id:id,status:value});setTasks(current=>current.map(item=>item.id===id?{...item,status:value,offline_pending:true}:item));announce('Status saved offline',`“${task?.title||'Task'}” will sync when your connection returns.`);return}catch(queueError){e=queueError}}setError(e.message);announce('Update failed',e.message,'error')}};
  const remove=async id=>{const task=tasks.find(item=>item.id===id);if(id<0||!navigator.onLine){try{enqueueDeletion(id,user.id);setTasks(current=>current.filter(item=>item.id!==id));announce('Task deletion queued',`“${task?.title||'Task'}” will be removed when pending changes sync.`);return}catch(e){setError(e.message);announce('Deletion not saved',e.message,'error');return}}try{await call('/tasks/'+id,'DELETE');announce('Task deleted',`“${task?.title||'Task'}” was removed.`);load()}catch(e){if(e instanceof TypeError){try{enqueueDeletion(id,user.id);setTasks(current=>current.filter(item=>item.id!==id));announce('Task deletion saved offline',`“${task?.title||'Task'}” will be deleted when your connection returns.`);return}catch(queueError){e=queueError}}setError(e.message);announce('Delete failed',e.message,'error')}};
  const updateDependencies=async(id,depends_on_ids)=>{try{await call(`/tasks/${id}/dependencies`,'PUT',{depends_on_ids});announce('Dependencies updated','Task prerequisites were saved.');await load();return true}catch(e){setError(e.message);announce('Dependencies not saved',e.message,'error');return false}};
  const reschedule=async(id,scheduled_start)=>{const task=tasks.find(item=>item.id===id);if(!task)return;try{const check=await call('/calendar/conflicts','POST',{task_id:id,scheduled_start,duration_minutes:task.estimated_minutes||30});if(check.conflicts.length){const names=check.conflicts.map(item=>item.title).join(', '),suggested=check.suggestions?.length?` Try ${check.suggestions.map(value=>new Date(value).toLocaleString()).join(' or ')}.`:'';announce('Time conflict',`This time overlaps ${names}.${suggested}`,'error');return}await call(`/tasks/${id}`,'PUT',{scheduled_start});await load();announce('Task rescheduled',`“${task.title}” was scheduled for ${new Date(scheduled_start).toLocaleString()}.`)}catch(e){setError(e.message);announce('Reschedule failed',e.message,'error')}};
  const download=async(path,filename)=>{try{const response=await fetch(API+path,{headers:{Authorization:'Bearer '+localStorage.getItem('tm_token')}});if(!response.ok){const data=await response.json().catch(()=>({}));throw Error(data.error?.message||'Download failed')}const url=URL.createObjectURL(await response.blob()),link=document.createElement('a');link.href=url;link.download=filename;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);announce('Download ready',`${filename} was downloaded.`)}catch(e){setError(e.message);announce('Download failed',e.message,'error')}};
  const restore=async event=>{const file=event.target.files?.[0];event.target.value='';if(!file)return;try{const data=JSON.parse(await file.text()),result=await call('/import/backup','POST',data);await load();announce('Backup restored',`${result.imported_tasks} tasks were imported.`)}catch(e){setError(e.message);announce('Restore failed',e.message,'error')}};
  const uploadAttachment=async(taskId,file)=>{const form=new FormData();form.append('file',file);try{const response=await fetch(`${API}/tasks/${taskId}/attachments`,{method:'POST',headers:{Authorization:'Bearer '+localStorage.getItem('tm_token')},body:form});const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error?.message||'Attachment upload failed');announce('Attachment uploaded',`${data.attachment.filename} was attached.`);return true}catch(e){setError(e.message);announce('Attachment upload failed',e.message,'error');return false}};
  const deleteAttachment=async(id)=>{try{await call(`/attachments/${id}`,'DELETE');announce('Attachment removed','The task file was deleted.');return true}catch(e){setError(e.message);announce('Attachment could not be removed',e.message,'error');return false}};
  if(!user)return <Auth onDone={setUser}/>;
  return <div className={'shell '+(focusMode?'focusMode':'')}><aside><div className="logo">✓ TaskMaster <b>Pro</b></div>{nav.map(([name,Icon])=><button key={name} className={page===name?'active':''} onClick={()=>setPage(name)}><Icon size={18}/>{name}</button>)}<button className="logout" onClick={()=>{localStorage.removeItem('tm_token');setUser(null)}}><LogOut size={18}/>Log out</button></aside><main className="app"><header><div><p className="eyebrow">{new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})}</p><h1>{page}</h1></div><div className="headerActions"><span>{user.name}</span><button className="secondary notificationToggle" onClick={enableDesktopNotifications} disabled={desktopEnabled} title={desktopEnabled?'Desktop notifications enabled':'Enable desktop notifications'}><Bell size={17}/>{desktopEnabled?'Notifications on':'Enable alerts'}</button><NewTask onAdd={saveTask}/></div></header>{error&&<div className="notice">{error}<button onClick={()=>setError('')}>×</button></div>}<Page name={page} tasks={tasks} overview={overview} focusMode={focusMode} onToggleFocus={()=>setFocusMode(value=>!value)} onAdd={saveTask} onStatus={status} onDelete={remove} onDependencies={updateDependencies} onReschedule={reschedule} onUploadAttachment={uploadAttachment} onDeleteAttachment={deleteAttachment} onDownloadAttachment={(id,filename)=>download(`/attachments/${id}`,filename)} onExportCSV={()=>download('/export/tasks.csv','taskmaster-tasks.csv')} onExportCalendar={()=>download('/export/calendar.ics','taskmaster-calendar.ics')} onExportBackup={()=>download('/export/backup','taskmaster-backup.json')} onRestore={restore} reload={load} announce={announce}/></main>{notice&&<Toast notice={notice} onClose={()=>setNotice(null)}/>}</div>
}
function Page(p){if(p.name==='Dashboard')return <Dashboard {...p}/>;if(p.name==='My Tasks')return <TaskList {...p}/>;if(p.name==='Projects')return <Projects tasks={p.tasks} reload={p.reload} announce={p.announce}/>;if(p.name==='Collaboration')return <Collaboration tasks={p.tasks} announce={p.announce}/>;if(p.name==='Calendar')return <Calendar tasks={p.tasks} onReschedule={p.onReschedule}/>;if(p.name==='Task Progress Board')return <Kanban {...p}/>;if(p.name==='AI Assistant')return <Assistant onAdd={p.onAdd} tasks={p.tasks} reload={p.reload} announce={p.announce}/>;if(p.name==='Smart Scheduler')return <Scheduler announce={p.announce} reload={p.reload}/>;if(p.name==='Analytics')return <><Analytics {...p}/><WeeklyTrend/></>;if(p.name==='Focus Mode')return <><button className="secondary focusModeToggle" onClick={p.onToggleFocus}>{p.focusMode?'Exit distraction-free focus':'Enter distraction-free focus'}</button><Focus announce={p.announce} tasks={p.tasks}/></>;if(p.name==='Notifications')return <Notifications/>;if(p.name==='Settings')return <SettingsPage announce={p.announce}/>;return <Empty text="Page not found."/>}
function TaskList({tasks,onStatus,onDelete,onDependencies,onExportCSV,onExportCalendar,onExportBackup,onRestore,onUploadAttachment,onDeleteAttachment,onDownloadAttachment}){const[query,setQuery]=useState(''),[results,setResults]=useState(tasks),[loading,setLoading]=useState(false),[error,setError]=useState('');useEffect(()=>{if(!query.trim()){setResults(tasks);setError('');return}const timer=setTimeout(async()=>{setLoading(true);try{const d=await call('/tasks?q='+encodeURIComponent(query.trim()));setResults(d.tasks);setError('')}catch(e){setError(e.message)}finally{setLoading(false)}},250);return()=>clearTimeout(timer)},[query,tasks]);function voiceCommand(){const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){setError('Voice commands are not supported in this browser. Try Chrome or Edge.');return}const recognition=new Recognition();recognition.lang=navigator.language||'en-US';recognition.interimResults=false;recognition.onresult=event=>{const phrase=event.results[0][0].transcript.trim(),command=phrase.match(/^(complete|finish|start|begin)\s+(.+)$/i);if(!command){setQuery(phrase);return}const task=tasks.find(item=>item.title.toLowerCase().includes(command[2].toLowerCase()));if(!task){setError(`No task matched “${command[2]}”.`);return}onStatus(task.id,/^(complete|finish)$/i.test(command[1])?'completed':'in_progress')};recognition.onerror=()=>setError('Voice command failed. Check microphone permission and try again.');recognition.start()}return <section><div className="taskToolbar"><div className="voiceSearchControl"><label className="searchField"><Search size={17}/><input type="search" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search titles, descriptions, categories, and tags"/></label><button className="secondary" title="Search or update tasks by voice" onClick={voiceCommand}><Mic size={16}/><span>Voice</span></button></div><div className="row"><button className="secondary" onClick={onExportCSV}><Download size={16}/>CSV</button><button className="secondary" onClick={onExportCalendar}><CalendarDays size={16}/>Calendar</button><button className="secondary" onClick={onExportBackup}><Download size={16}/>Backup</button><label className="secondary uploadButton">Restore<input type="file" accept="application/json,.json" onChange={onRestore}/></label></div></div>{loading&&<p className="eyebrow">Searching…</p>}{error&&<p className="error">{error}</p>}<div className="cards">{results.map(t=><TaskCard key={t.id} task={t} onStatus={onStatus} onDelete={onDelete} allTasks={tasks} onDependencies={onDependencies} onUploadAttachment={onUploadAttachment} onDeleteAttachment={onDeleteAttachment} onDownloadAttachment={onDownloadAttachment}/>)}</div>{!results.length&&<Empty text={query?'No tasks matched your search.':'Your task list is clear. Add a task to get started.'}/>}</section>}
function Projects({tasks,reload,announce}){const[projects,setProjects]=useState([]),[name,setName]=useState(''),[description,setDescription]=useState(''),[selectedTask,setSelectedTask]=useState({}),[milestoneDraft,setMilestoneDraft]=useState({}),[error,setError]=useState('');async function loadProjects(){try{setProjects((await call('/projects')).projects);setError('')}catch(e){setError(e.message)}}useEffect(()=>{loadProjects()},[]);async function createProject(e){e.preventDefault();try{const d=await call('/projects','POST',{name,description});setProjects(current=>[...current,d.project].sort((a,b)=>a.name.localeCompare(b.name)));setName('');setDescription('');announce('Project created',`“${d.project.name}” is ready.`)}catch(e){setError(e.message)}}async function addTask(project){const taskId=Number(selectedTask[project.id]);if(!taskId)return;try{const ids=Array.from(new Set([...project.task_ids,taskId]));const d=await call(`/projects/${project.id}/tasks`,'PUT',{task_ids:ids});setProjects(current=>current.map(p=>p.id===project.id?d.project:p));setSelectedTask(current=>({...current,[project.id]:''}));await reload()}catch(e){setError(e.message)}}async function addMilestone(e,project){e.preventDefault();const title=milestoneDraft[project.id]?.title||'',due_date=milestoneDraft[project.id]?.due_date||null;try{await call(`/projects/${project.id}/milestones`,'POST',{title,due_date});setMilestoneDraft(current=>({...current,[project.id]:{title:'',due_date:''}}));await loadProjects();announce('Milestone added',`A milestone was added to ${project.name}.`)}catch(e){setError(e.message)}}async function toggleMilestone(project,milestone){try{await call(`/projects/${project.id}/milestones/${milestone.id}`,'PATCH',{completed:!milestone.completed});await loadProjects()}catch(e){setError(e.message)}}async function removeProject(project){if(!confirm(`Delete project “${project.name}”? Tasks will not be deleted.`))return;try{await call(`/projects/${project.id}`,'DELETE');await loadProjects();await reload();announce('Project deleted',`“${project.name}” was removed.`)}catch(e){setError(e.message)}}async function detachTask(project,taskId){try{const d=await call(`/projects/${project.id}/tasks`,'PUT',{task_ids:project.task_ids.filter(id=>id!==taskId)});setProjects(current=>current.map(p=>p.id===project.id?d.project:p));await reload()}catch(e){setError(e.message)}}return <section className="projectsPage"><form className="panel projectForm" onSubmit={createProject}><h2>Create a project</h2><input value={name} onChange={e=>setName(e.target.value)} placeholder="Project name" maxLength={120} required/><textarea value={description} onChange={e=>setDescription(e.target.value)} placeholder="Description (optional)" maxLength={2000}/><button><Plus size={16}/>Create project</button></form>{error&&<p className="error">{error}</p>}<div className="projectGrid">{projects.map(project=><article className="panel projectCard" key={project.id}><header><div><h2>{project.name}</h2><p>{project.description||'No description'}</p></div><button className="text" onClick={()=>removeProject(project)}>Delete</button></header><div className="projectProgress"><span>{project.completed_tasks} of {project.task_count} tasks complete</span><b>{project.progress_percentage}%</b><progress max="100" value={project.progress_percentage}/></div><div className="projectTasks">{project.task_ids.map(taskId=>{const task=tasks.find(t=>t.id===taskId);return task&&<div className="review" key={taskId}><span>{task.title} · {task.status.replace('_',' ')}</span><button className="text" onClick={()=>detachTask(project,taskId)}>Remove</button></div>})}</div><form className="projectAttach" onSubmit={e=>{e.preventDefault();addTask(project)}}><select aria-label={`Add task to ${project.name}`} value={selectedTask[project.id]||''} onChange={e=>setSelectedTask(current=>({...current,[project.id]:e.target.value}))}><option value="">Choose a task to add</option>{tasks.filter(t=>!project.task_ids.includes(t.id)).map(t=><option key={t.id} value={t.id}>{t.title}</option>)}</select><button className="secondary" disabled={!selectedTask[project.id]}>Add task</button></form><h3>Milestones</h3>{project.milestones.map(milestone=><div className="milestone" key={milestone.id}><label><input type="checkbox" checked={milestone.completed} onChange={()=>toggleMilestone(project,milestone)}/>{milestone.title}</label><small>{milestone.due_date?new Date(milestone.due_date).toLocaleDateString():'No due date'}</small></div>)}<form className="milestoneForm" onSubmit={e=>addMilestone(e,project)}><input placeholder="New milestone" maxLength={200} value={milestoneDraft[project.id]?.title||''} onChange={e=>setMilestoneDraft(current=>({...current,[project.id]:{...current[project.id],title:e.target.value}}))} required/><input aria-label="Milestone deadline" type="datetime-local" value={milestoneDraft[project.id]?.due_date||''} onChange={e=>setMilestoneDraft(current=>({...current,[project.id]:{...current[project.id],due_date:e.target.value}}))}/><button className="secondary">Add milestone</button></form></article>)}</div>{!projects.length&&<Empty text="Create a project to group tasks and track milestones."/>}</section>}
function Collaboration({tasks,announce}){const[projects,setProjects]=useState([]),[shared,setShared]=useState([]),[error,setError]=useState('');async function reload(){try{const[owned,sharedProjects]=await Promise.all([call('/projects'),call('/shared/projects')]);setProjects(owned.projects);setShared(sharedProjects.projects);setError('')}catch(e){setError(e.message)}}useEffect(()=>{reload()},[]);return <section className="collaborationPage"><section className="panel"><h2>Invite teammates to projects</h2><p>Invite existing TaskMaster accounts by email, discuss project work, and assign project tasks to members.</p></section>{error&&<p className="error">{error}</p>}<h2>Your projects</h2><div className="collabGrid">{projects.map(project=><OwnedCollaboration key={project.id} project={project} tasks={tasks} reload={reload} announce={announce}/>)}</div>{!projects.length&&<Empty text="Create a project before inviting collaborators."/>}<h2>Shared with you</h2><div className="collabGrid">{shared.map(item=><SharedCollaboration key={item.project.id} item={item} reload={reload} announce={announce}/>)}</div>{!shared.length&&<p>You have no shared projects yet.</p>}</section>}
function OwnedCollaboration({project,tasks,reload,announce}){const[members,setMembers]=useState([]),[assignments,setAssignments]=useState([]),[email,setEmail]=useState(''),[taskId,setTaskId]=useState(''),[memberId,setMemberId]=useState(''),[error,setError]=useState('');async function load(){try{const[m,a]=await Promise.all([call(`/projects/${project.id}/members`),call(`/projects/${project.id}/assignments`)]);setMembers(m.members);setAssignments(a.assignments);setError('')}catch(e){setError(e.message)}}useEffect(()=>{load()},[project.id]);async function addMember(event){event.preventDefault();try{await call(`/projects/${project.id}/members`,'POST',{email});setEmail('');await load();announce('Collaborator added',`${email} can now see this project.`)}catch(e){setError(e.message)}}async function changeAssignments(next){try{await call(`/projects/${project.id}/assignments`,'PUT',{assignments:next});setAssignments(await call(`/projects/${project.id}/assignments`).then(data=>data.assignments));setTaskId('');announce('Assignments updated','Project task assignments were saved.')}catch(e){setError(e.message)}}async function removeMember(id){try{await call(`/projects/${project.id}/members/${id}`,'DELETE');await load()}catch(e){setError(e.message)}}return <article className="panel collaborationCard"><h3>{project.name}</h3>{error&&<p className="error">{error}</p>}<form className="inlineForm" onSubmit={addMember}><input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="Existing account email" required/><button className="secondary">Invite</button></form><div className="memberList">{members.map(member=><div className="review" key={member.id}><span>{member.name} · {member.email}</span><button className="text" onClick={()=>removeMember(member.id)}>Remove</button></div>)}</div><form className="inlineForm" onSubmit={e=>{e.preventDefault();if(taskId&&memberId)changeAssignments([...assignments.filter(item=>item.task_id!==Number(taskId)||item.user_id!==Number(memberId)),{task_id:Number(taskId),user_id:Number(memberId)}])}}><select value={taskId} onChange={e=>setTaskId(e.target.value)} required><option value="">Project task</option>{project.task_ids.map(id=><option key={id} value={id}>{tasks.find(task=>task.id===id)?.title||`Task #${id}`}</option>)}</select><select value={memberId} onChange={e=>setMemberId(e.target.value)} required><option value="">Project member</option>{members.map(member=><option key={member.id} value={member.id}>{member.name}</option>)}</select><button className="secondary" disabled={!members.length||!project.task_count}>Assign</button></form>{assignments.map(item=><div className="review" key={`${item.task_id}-${item.user_id}`}><span>{tasks.find(task=>task.id===item.task_id)?.title||`Task #${item.task_id}`} → {item.name}</span><button className="text" onClick={()=>changeAssignments(assignments.filter(value=>value.task_id!==item.task_id||value.user_id!==item.user_id))}>Unassign</button></div>)}<ProjectComments projectId={project.id} announce={announce}/></article>}
function SharedCollaboration({item,reload,announce}){async function setStatus(taskId,status){try{await call(`/assigned-tasks/${taskId}/status`,'PATCH',{status});await reload()}catch(e){announce('Task update failed',e.message,'error')}}return <article className="panel collaborationCard"><h3>{item.project.name}</h3><p>Shared by {item.owner}</p>{item.tasks.map(task=><div className="review" key={task.id}><div><b>{task.title}</b><small>{task.status.replace('_',' ')}{task.assigned_to_me?' · assigned to you':''}</small></div>{task.assigned_to_me&&<select aria-label={`Update ${task.title}`} value={task.status} onChange={e=>setStatus(task.id,e.target.value)}><option value="todo">To do</option><option value="in_progress">In progress</option><option value="completed">Completed</option></select>}</div>)}<ProjectComments projectId={item.project.id} announce={announce}/></article>}
function ProjectComments({projectId,announce}){const[comments,setComments]=useState([]),[message,setMessage]=useState(''),[error,setError]=useState('');async function load(){try{setComments((await call(`/projects/${projectId}/comments`)).comments);setError('')}catch(e){setError(e.message)}}useEffect(()=>{load()},[projectId]);async function post(event){event.preventDefault();try{await call(`/projects/${projectId}/comments`,'POST',{message});setMessage('');await load();announce('Comment added','Your project comment was shared.')}catch(e){setError(e.message)}}return <div className="projectComments"><h4>Discussion</h4>{error&&<small className="error">{error}</small>}{comments.map(comment=><p className="projectComment" key={comment.id}><b>{comment.author}</b><span>{comment.message}</span><small>{new Date(comment.created_at).toLocaleString()}</small></p>)}<form className="inlineForm" onSubmit={post}><input maxLength={2000} value={message} onChange={e=>setMessage(e.target.value)} placeholder="Add a comment" required/><button className="secondary">Comment</button></form></div>}
function Dashboard({tasks,overview,onStatus,onDelete}){const today=tasks.filter(t=>t.status!=='completed').slice(0,4);return <><section className="welcome"><div><span>YOUR PRODUCTIVITY, SIMPLIFIED</span><h2>Make today count, one task at a time.</h2><p>Prioritize what matters and keep your momentum.</p></div><Sparkles/></section><div className="metrics">{[['Total tasks',overview?.total_tasks],['Completed',overview?.completed_tasks],['Pending',overview?.pending_tasks],['Overdue',overview?.overdue_tasks]].map(([a,b])=><div className="metric" key={a}><p>{a}</p><strong>{b??'—'}</strong></div>)}</div><section><div className="sectionTitle"><h2>Up next</h2><span>{overview?.completion_percentage??0}% complete</span></div><div className="cards">{today.map(t=><TaskCard key={t.id} task={t} onStatus={onStatus} onDelete={onDelete}/>)}</div>{!today.length&&<Empty text="No pending tasks — enjoy the breathing room."/>}</section></>}
function Calendar({tasks,onReschedule}){const[mode,setMode]=useState('month'),[cursor,setCursor]=useState(()=>new Date()),[dragging,setDragging]=useState(null);const dateKey=date=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;const events=tasks.filter(task=>task.scheduled_start||task.due_date);const start=new Date(cursor);if(mode==='month'){start.setDate(1);start.setDate(1-start.getDay())}else if(mode==='week')start.setDate(start.getDate()-start.getDay());start.setHours(0,0,0,0);const days=Array.from({length:mode==='month'?42:mode==='week'?7:1},(_,index)=>{const day=new Date(start);day.setDate(start.getDate()+index);return day});function move(amount){const next=new Date(cursor);if(mode==='month'){next.setDate(1);next.setMonth(next.getMonth()+amount)}else next.setDate(next.getDate()+amount*(mode==='week'?7:1));setCursor(next)}async function drop(event,day){event.preventDefault();const taskId=Number(event.dataTransfer.getData('text/task-id'));if(!taskId)return;const scheduled=new Date(day);scheduled.setHours(9,0,0,0);setDragging(null);await onReschedule(taskId,scheduled.toISOString())}return <section className="calendar panel"><div className="calendarToolbar"><div className="row"><button className="secondary" onClick={()=>move(-1)} aria-label="Previous period">‹</button><button className="secondary" onClick={()=>setCursor(new Date())}>Today</button><button className="secondary" onClick={()=>move(1)} aria-label="Next period">›</button></div><h2>{cursor.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</h2><div className="row">{['month','week','day'].map(value=><button className={mode===value?'primary':'secondary'} key={value} onClick={()=>setMode(value)}>{value[0].toUpperCase()+value.slice(1)}</button>)}</div></div><p>Drag a task to another day to schedule it at 9:00 AM. Existing due dates remain unchanged.</p>{mode!=='day'&&<div className="calendarWeekdays">{['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(day=><b key={day}>{day}</b>)}</div>}<div className={'calendarGrid '+mode}>{days.map(day=>{const dayEvents=events.filter(task=>dateKey(new Date(task.scheduled_start||task.due_date))===dateKey(day));return <section key={dateKey(day)} className={'calendarCell '+(dateKey(day)===dateKey(new Date())?'today':'')} onDragOver={event=>event.preventDefault()} onDrop={event=>drop(event,day)}><h3>{mode==='day'?day.toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}):<>{mode==='month'?day.getDate():day.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</>}</h3>{dayEvents.map(task=><div className={'calendarEvent '+(dragging===task.id?'dragging':'')} draggable key={task.id} onDragStart={event=>{event.dataTransfer.setData('text/task-id',String(task.id));setDragging(task.id)}} onDragEnd={()=>setDragging(null)} title={`${task.title} · ${task.due_date?'Due date':'Scheduled'}`}><b>{task.title}</b><small>{task.scheduled_start?'Scheduled':'Due date'} · {task.priority}</small></div>)}</section>})}</div>{!events.length&&<Empty text="Add a due date or schedule a task to see it here."/>}</section>}
function Kanban({tasks,onStatus,onDelete}){return <div className="kanban">{[['todo','To do'],['in_progress','In progress'],['completed','Completed']].map(([key,label])=><section key={key}><h2>{label}<span>{tasks.filter(t=>t.status===key).length}</span></h2>{tasks.filter(t=>t.status===key).map(t=><TaskCard key={t.id} task={t} onStatus={onStatus} onDelete={onDelete}/>)}</section>)}</div>}
function Assistant({onAdd,tasks,reload,announce}){const[input,setInput]=useState(''),[loading,setLoading]=useState(false),[reply,setReply]=useState(''),[plan,setPlan]=useState([]),[parsed,setParsed]=useState(null),[taskId,setTaskId]=useState(''),[steps,setSteps]=useState([]),[recommendation,setRecommendation]=useState(null),[briefing,setBriefing]=useState(''),[error,setError]=useState('');async function perform(action){setLoading(true);setError('');try{await action()}catch(e){setError(e.message)}finally{setLoading(false)}}async function ask(e){e.preventDefault();await perform(async()=>{const d=await call('/ai/chat','POST',{message:input});setReply(d.reply)})}async function generate(){await perform(async()=>{const d=await call('/ai/generate-tasks','POST',{prompt:input});setPlan(d.tasks);announce('Task plan ready',`${d.tasks.length} suggested task${d.tasks.length===1?'':'s'} are ready for review.`)})}async function extractTask(){await perform(async()=>{const d=await call('/ai/parse-task','POST',{prompt:input});setParsed(d.task)})}async function breakDown(){await perform(async()=>{const d=await call('/ai/breakdown','POST',{task_id:Number(taskId)});setSteps(d.subtasks)})}async function saveSteps(){await perform(async()=>{await call(`/tasks/${taskId}/subtasks/bulk`,'POST',{subtasks:steps});setSteps([]);await reload();announce('Task breakdown saved',`${steps.length} steps were added to the task.`)})}async function prioritize(){await perform(async()=>{const d=await call('/ai/prioritize','POST',{});setRecommendation(d.recommendation)})}async function getBriefing(){await perform(async()=>{const d=await call('/ai/briefing');setBriefing(d.briefing)})}return <section className="assistant"><div className="panel"><span className="aiBadge"><Sparkles size={16}/> LIVE AI</span><h2>How can I help?</h2><p>Ask about your work, generate tasks, or use AI to manage your workday.</p><form onSubmit={ask}><label>Your request <Hint>Chat answers using your task context. Generate tasks creates a reviewable plan. Extract task reads a natural-language instruction into task fields for your approval.</Hint><textarea value={input} onChange={e=>setInput(e.target.value)} placeholder="Finish my project by Friday at 5 PM…" required/></label><div className="row"><button type="button" className="secondary" onClick={generate} disabled={loading}>Generate task plan</button><button type="button" className="secondary" onClick={extractTask} disabled={loading}>Extract task</button><button disabled={loading}><Send size={16}/>{loading?'Thinking…':'Ask assistant'}</button></div></form><div className="row aiActions"><button className="secondary" onClick={prioritize} disabled={loading}>Recommend next task</button><button className="secondary" onClick={getBriefing} disabled={loading}>Daily briefing</button></div><label>Break down a task<select value={taskId} onChange={e=>{setTaskId(e.target.value);setSteps([])}}><option value="">Select an unfinished task</option>{tasks.filter(t=>t.status!=='completed').map(t=><option key={t.id} value={t.id}>{t.title}</option>)}</select></label><button className="secondary" onClick={breakDown} disabled={loading||!taskId}>Generate steps</button>{error&&<p className="error">{error}</p>}{reply&&<div className="reply">{reply}</div>}{recommendation&&<div className="reply"><b>Next up: {recommendation.title}</b><p>{recommendation.reason}</p></div>}{briefing&&<div className="reply"><b>Daily briefing</b><p>{briefing}</p></div>}{steps.length>0&&<div className="reply"><b>Suggested subtasks</b><ul>{steps.map((step,i)=><li key={i}>{step.title}</li>)}</ul><button onClick={saveSteps} disabled={loading}>Add these steps to task</button></div>}</div>{parsed&&<div className="panel"><h2>Review extracted task</h2><div className="review"><div><b>{parsed.title}</b><small>{parsed.priority} · {parsed.estimated_minutes} min{parsed.due_date?` · Due ${new Date(parsed.due_date).toLocaleString()}`:''}</small>{parsed.subtasks?.length>0&&<ul>{parsed.subtasks.map((s,i)=><li key={i}>{s.title}</li>)}</ul>}</div><button onClick={async()=>{if(await onAdd(parsed))setParsed(null)}}>Create task</button></div></div>}{plan.length>0&&<div className="panel"><h2>Review generated tasks</h2><p>Nothing is saved until you approve it.</p>{plan.map((task,i)=><div className="review" key={i}><div><b>{task.title}</b><small>{task.priority} · {task.estimated_minutes} min{task.due_date?` · Due ${new Date(task.due_date).toLocaleDateString()}`:''}</small>{task.subtasks?.length>0&&<ul>{task.subtasks.map((step,n)=><li key={n}>{step.title}</li>)}</ul>}</div><button onClick={async()=>{if(await onAdd(task))setPlan(current=>current.filter((_,index)=>index!==i))}}>Approve</button></div>)}</div>}</section>}
function Scheduler({announce,reload}){const[schedule,setSchedule]=useState(null),[unscheduled,setUnscheduled]=useState([]),[loading,setLoading]=useState(false),[error,setError]=useState('');async function make(){setLoading(true);setError('');try{const result=await call('/ai/schedule','POST',{});setSchedule(result.schedule);setUnscheduled(result.unscheduled||[]);announce('Schedule ready',`${result.schedule.length} task${result.schedule.length===1?'':'s'} ready to apply.${result.unscheduled?.length?` ${result.unscheduled.length} task${result.unscheduled.length===1?' was':'s were'} too long for the workday.`:''}`)}catch(e){setError(e.message)}finally{setLoading(false)}}async function apply(){setLoading(true);setError('');try{const result=await call('/schedule/apply','POST',{schedule});await reload();setSchedule(null);announce('Schedule applied',`${result.scheduled_tasks.length} task times were saved to your calendar.`)}catch(e){setError(e.message)}finally{setLoading(false)}}return <section className="panel"><h2>Plan your focused week</h2><p>Suggestions use priority, due dates, estimated duration, and existing scheduled tasks. They fit within your configured workday. Apply the preview to save task times to your calendar.</p><button onClick={make} disabled={loading}>{loading?'Building preview…':'Build schedule preview'}</button>{error&&<p className="error">{error}</p>}{schedule?.map(x=><div className="review" key={x.task_id}><div><b>{x.title}</b><small>{new Date(x.suggested_start).toLocaleString()} · {x.duration_minutes} min</small></div><span>{x.reason}</span></div>)}{schedule?.length===0&&unscheduled.length===0&&<p>No unscheduled pending tasks. Add a task or clear its existing schedule.</p>}{unscheduled.length>0&&<><h3>Not scheduled</h3>{unscheduled.map(x=><div className="review" key={x.task_id}><div><b>{x.title}</b><small>{x.reason}</small></div></div>)}</>}{schedule?.length>0&&<button onClick={apply} disabled={loading}>Apply schedule</button>}</section>}
function Analytics({overview}){const data=Object.entries(overview?.by_priority||{}).map(([name,value])=>({name,value})),goals=overview?.goals||{},gamification=overview?.gamification||{};return <><div className="metrics"><div className="metric"><p>Completion rate</p><strong>{overview?.completion_percentage??0}%</strong></div><div className="metric"><p>Estimated time</p><strong>{overview?.estimated_minutes??0}m</strong></div><div className="metric"><p>Actual time</p><strong>{overview?.actual_minutes??0}m</strong></div><div className="metric"><p>Points · current streak</p><strong>{gamification.points??0} · {gamification.streak_days??0}d</strong></div></div><div className="goalGrid">{[['Daily goal',goals.daily],['Weekly goal',goals.weekly]].map(([name,value])=><section className="panel goalCard" key={name}><h2>{name}</h2><p>{value?.completed??0} of {value?.target??0} tasks completed</p><progress max={value?.target||1} value={Math.min(value?.completed||0,value?.target||1)}/></section>)}</div><section className="panel chart"><h2>Tasks by priority</h2><ResponsiveContainer width="100%" height={280}><BarChart data={data}><XAxis dataKey="name"/><YAxis allowDecimals={false}/><Tooltip/><Bar dataKey="value" fill="#705cf6" radius={[7,7,0,0]}/></BarChart></ResponsiveContainer></section><section className="panel badges"><h2>Achievements</h2><div className="badgeGrid">{(gamification.badges||[]).map(badge=><article className={badge.earned?'achievement earned':'achievement'} key={badge.id}><b>{badge.name}</b><small>{badge.description}</small><span>{badge.earned?'Earned':'Locked'}</span></article>)}</div></section></>}
function Focus({announce,tasks}){const[seconds,setSeconds]=useState(25*60),[running,setRunning]=useState(false),[started,setStarted]=useState(null),[pausedAt,setPausedAt]=useState(null),[mode,setMode]=useState('focus'),[taskId,setTaskId]=useState(''),[history,setHistory]=useState(null),[error,setError]=useState('');const sessionLength=mode==='focus'?25:5;async function saveSession(endTime){const start=started;setRunning(false);setStarted(null);setPausedAt(null);if(!start)return;try{const response=await call('/focus-sessions','POST',{start_time:start,end_time:endTime||new Date().toISOString(),session_type:mode,task_id:mode==='focus'&&taskId?Number(taskId):undefined});announce(`${mode==='focus'?'Focus':'Break'} session saved`,`${response.session.duration_minutes} minutes were recorded.`);setHistory((await call('/focus-sessions')).sessions)}catch(e){announce('Session not saved',e.message||'Please try saving your session again.','error')}}useEffect(()=>{if(!running)return;const timer=setInterval(()=>setSeconds(value=>{if(value<=1){setRunning(false);return 0}return value-1}),1000);return()=>clearInterval(timer)},[running]);useEffect(()=>{if(seconds===0&&started)saveSession()},[seconds,started]);useEffect(()=>{call('/focus-sessions').then(data=>setHistory(data.sessions)).catch(e=>setError(e.message))},[]);function toggle(){if(running){setRunning(false);setPausedAt(Date.now());return}if(started){const adjusted=new Date(new Date(started).getTime()+Date.now()-pausedAt).toISOString();setStarted(adjusted);setPausedAt(null);setRunning(true);return}setSeconds(sessionLength*60);setStarted(new Date().toISOString());setRunning(true)}function reset(){setRunning(false);setStarted(null);setPausedAt(null);setSeconds(sessionLength*60)}return <><section className="focus panel"><span className="aiBadge">FOCUS MODE · {mode.toUpperCase()}</span><h2>{String(Math.floor(seconds/60)).padStart(2,'0')}:{String(seconds%60).padStart(2,'0')}</h2><p>{mode==='focus'?'Work for 25 minutes, then take a five-minute break.':'Take a short break before your next focus session.'}</p><div className="row focusOptions"><select aria-label="Session type" value={mode} onChange={e=>{setMode(e.target.value);setSeconds(e.target.value==='focus'?25*60:5*60)}} disabled={running||Boolean(started)}><option value="focus">Focus · 25 minutes</option><option value="break">Break · 5 minutes</option></select>{mode==='focus'&&<select aria-label="Associate session with task" value={taskId} onChange={e=>setTaskId(e.target.value)} disabled={running||Boolean(started)}><option value="">No task selected</option>{tasks.filter(task=>task.status!=='completed').map(task=><option key={task.id} value={task.id}>{task.title}</option>)}</select>}</div><div className="timerControls"><button aria-label={running?'Pause timer':'Start or resume timer'} onClick={toggle}>{running?<Pause/>:<Play/>}</button><button className="secondary" onClick={reset}><RotateCcw/></button><button className="text" onClick={()=>saveSession(pausedAt?new Date(pausedAt).toISOString():undefined)} disabled={!started}>Save session</button></div></section><section className="panel sessionHistory"><h2>Session history</h2>{error&&<p className="error">{error}</p>}{history?.map(session=><div className="review" key={`${session.session_type}-${session.id}`}><div><b>{session.session_type==='focus'?'Focus':'Break'}{session.task_title?` · ${session.task_title}`:''}</b><small>{new Date(session.start_time).toLocaleString()}</small></div><span>{session.duration_minutes} min</span></div>)}{history?.length===0&&<p>No recorded sessions yet.</p>}</section></>}
function Notifications(){const[items,setItems]=useState([]),[unread,setUnread]=useState(0),[error,setError]=useState('');async function load(){try{const data=await call('/notifications');setItems(data.notifications);setUnread(data.unread_count);setError('')}catch(e){setError(e.message)}}useEffect(()=>{load()},[]);async function markRead(id){try{await call(`/notifications/${id}/read`,'PATCH',{});await load()}catch(e){setError(e.message)}}async function markAll(){try{await call('/notifications/read-all','POST',{});await load()}catch(e){setError(e.message)}}return <section className="panel notificationPage"><div className="sectionTitle"><h2>Notifications <span>{unread} unread</span></h2>{unread>0&&<button className="secondary" onClick={markAll}>Mark all read</button>}</div>{error&&<p className="error">{error}</p>}{items.map(item=><article className={'notificationItem '+(item.read_at?'read':'unread')} key={item.id}><div><b>{item.title}</b><p>{item.message}</p><small>{new Date(item.created_at).toLocaleString()}</small></div>{!item.read_at&&<button className="text" onClick={()=>markRead(item.id)}>Mark read</button>}</article>)}{!items.length&&!error&&<p>No notifications yet. Task updates and upcoming deadlines will appear here.</p>}</section>}
function SettingsPage({announce}){const[settings,setSettings]=useState({work_start_hour:9,work_end_hour:17,daily_goal_tasks:3,weekly_goal_tasks:15,notifications_enabled:true,theme:'light'}),[loading,setLoading]=useState(true),[error,setError]=useState('');useEffect(()=>{call('/preferences').then(data=>setSettings(value=>({...value,...data.preferences}))).catch(e=>setError(e.message)).finally(()=>setLoading(false))},[]);function update(key,value){setSettings(current=>({...current,[key]:value}))}async function save(event){event.preventDefault();setError('');try{const data=await call('/preferences','PUT',settings);setSettings(data.preferences);document.documentElement.dataset.theme=data.preferences.theme||'light';announce('Settings saved','Your workday, theme, reminders, and goals were updated.')}catch(e){setError(e.message)}}return <form className="panel settingsForm" onSubmit={save}><h2>Workday and goals</h2><p>These settings persist with your account and drive smart scheduling, reminders, and progress targets.</p>{error&&<p className="error">{error}</p>}<div className="row"><label>Workday starts<select value={settings.work_start_hour} onChange={e=>update('work_start_hour',Number(e.target.value))} disabled={loading}>{Array.from({length:24},(_,hour)=><option key={hour} value={hour}>{String(hour).padStart(2,'0')}:00</option>)}</select></label><label>Workday ends<select value={settings.work_end_hour} onChange={e=>update('work_end_hour',Number(e.target.value))} disabled={loading}>{Array.from({length:24},(_,hour)=><option key={hour} value={hour}>{String(hour).padStart(2,'0')}:00</option>)}</select></label></div><div className="row"><label>Daily task goal<input type="number" min="1" max="100" value={settings.daily_goal_tasks} onChange={e=>update('daily_goal_tasks',Number(e.target.value))} disabled={loading}/></label><label>Weekly task goal<input type="number" min="1" max="500" value={settings.weekly_goal_tasks} onChange={e=>update('weekly_goal_tasks',Number(e.target.value))} disabled={loading}/></label></div><label>Theme<select value={settings.theme||'light'} onChange={e=>update('theme',e.target.value)} disabled={loading}><option value="light">Light</option><option value="dark">Dark</option><option value="system">Use system preference</option></select></label><label className="settingToggle"><input type="checkbox" checked={settings.notifications_enabled!==false} onChange={e=>update('notifications_enabled',e.target.checked)} disabled={loading}/> Enable persistent due and overdue reminders</label><button disabled={loading}>{loading?'Loading settings…':'Save settings'}</button></form>}
function Empty({text}){return <div className="empty">✓<p>{text}</p></div>}createRoot(document.getElementById('root')).render(<App/>);
